import fs from 'node:fs';
import assert from 'node:assert/strict';
import {fileURLToPath} from 'node:url';
const source=fs.readFileSync(new URL('./raw-field-audit.ts',import.meta.url),'utf8');
const pure=source.split('// BEGIN PURE SUMMARY HELPERS')[1].split('// END PURE SUMMARY HELPERS')[0];
const {summarizeRows,summarizeNormalized,numericSourceShape}=new Function('Buffer',`${pure}\nreturn {summarizeRows,summarizeNormalized,numericSourceShape};`)(Buffer);
const secret='SECRET_NOT_ALLOWED_8765';
const a=summarizeRows([{ID:secret,PW:'150,170',POWER_KW:'88',INFO:`<table>engine capacity 1998 cc, power 150 hp ${secret}</table>`,EXTRA_TECH:secret,[`https://example.test/${secret}`]:secret}]);
const serialized=JSON.stringify(a);
assert(!serialized.includes(secret));
assert(!serialized.includes('example.test'));
assert.equal(a.rowCount,1);
assert.equal(a.omittedFieldNames,1);
assert.deepEqual(a.fields.find(f=>f.name==='PW').rawNumericExamples,['150,170']);
assert.deepEqual(a.fields.find(f=>f.name==='POWER_KW').rawNumericExamples,['88']);
assert(a.fieldsNotReadByAjesLot.includes('POWER_KW'));
assert(!a.fieldsNotReadByAjesLot.includes('PW'));
assert.equal(a.info[0].hasPowerTerm,true);
assert.equal(a.info[0].hasPowerUnit,true);
assert.equal(a.info[0].hasTableMarkup,true);
for(const bad of [secret,'https://example.test/150','150 hp','12345678','-1','99999',{},['150'],'150,'.repeat(100)])assert.equal(numericSourceShape(bad).rawNumeric,null);
assert.equal(numericSourceShape(null).kind,'missing');
assert.equal(numericSourceShape(150).rawNumeric,'150');
assert.equal(numericSourceShape('0').rawNumeric,'0');
const n=summarizeNormalized([{id:secret,sourcePower:'150,170',info:secret,engineCc:1500,equipment:secret},{sourcePower:'',powerHp:150,sourceDetails:{private:secret}}]);
assert.equal(n.sourcePowerPresent,1);assert.equal(n.powerHpPresent,1);assert.equal(n.infoPresent,1);assert.equal(n.sourceDetailsPresent,1);assert(!JSON.stringify(n).includes(secret));
assert.equal(summarizeRows(Array.from({length:3},()=>({PW:'150'}))).fields[0].present,3);
const many=Object.fromEntries(Array.from({length:200},(_,i)=>['FIELD_'+i,secret]));
assert.equal(summarizeRows([many]).fields.length,128);
assert.equal(summarizeRows([many]).omittedFieldNames,72);
assert(!/console\.(?:log|error)\([^\n]*(?:password|input|url|body|evidence|error\.(?:message|stack))/.test(source));
assert(source.includes('counters.supplierRequests>=2'));
assert(source.includes("callsForCurrent!==0"));
assert(source.includes("hasMatch===hasNone"));
console.log('raw-field-audit sanitizer checks passed');
